  <script>
    const products = [
      {
        name: 'Amber glass diffuser',
        category: 'Home fragrance',
        price: '$28',
        wasPrice: '$36',
        badge: 'Best seller',
        accent: 'AG',
        description: 'Warm citrus and cedar notes in a reusable bottle with minimalist packaging.'
      },
      {
        name: 'Everyday lounge mug',
        category: 'Kitchen',
        price: '$18',
        wasPrice: '$24',
        badge: 'New',
        accent: 'LM',
        description: 'A weighted ceramic mug designed for coffee, tea, and shelf appeal.'
      },
      {
        name: 'Studio tote pack',
        category: 'Accessories',
        price: '$42',
        wasPrice: '$52',
        badge: 'Trending',
        accent: 'ST',
        description: 'Durable carryall set with a clean profile for errands and weekend plans.'
      }
    ];

    const productsGrid = document.getElementById('products-grid');
    const cartButton = document.getElementById('cart-button');
    const cartCount = document.getElementById('cart-count');
    const newsletterForm = document.getElementById('newsletter-form');
    const newsletterHelp = document.getElementById('newsletter-help');
    let cartItems = 0;

    const productCards = products.map((product) => `
      <article class="section-card product-card">
        <div class="product-media">
          <div class="product-art" aria-hidden="true">${product.accent}</div>
        </div>
        <div class="product-body">
          <div class="product-meta">
            <span class="tag">${product.badge}</span>
            <span class="tag">${product.category}</span>
          </div>
          <h3>${product.name}</h3>
          <p>${product.description}</p>
          <div class="price-row">
            <div>
              <span class="price">${product.price}</span>
              <span class="was-price">${product.wasPrice}</span>
            </div>
            <span class="tag">4.8 ★</span>
          </div>
          <div class="action-row">
            <button class="button add-to-cart" type="button" aria-label="Add ${product.name} to cart">Add to cart</button>
            <button class="button-secondary" type="button" aria-label="Save ${product.name} for later">Save</button>
          </div>
        </div>
      </article>
    `).join('');

    productsGrid.innerHTML = productCards;

    const addButtons = document.querySelectorAll('.add-to-cart');
    addButtons.forEach((button) => {
      button.addEventListener('click', () => {
        cartItems += 1;
        cartCount.textContent = String(cartItems);
        cartButton.setAttribute('aria-label', `Cart with ${cartItems} item${cartItems === 1 ? '' : 's'}`);
        newsletterHelp.textContent = 'Item added to cart.';
      });
    });

    const targetSaleEnd = new Date();
    targetSaleEnd.setHours(targetSaleEnd.getHours() + 9);
    targetSaleEnd.setMinutes(targetSaleEnd.getMinutes() + 32);
    targetSaleEnd.setSeconds(targetSaleEnd.getSeconds() + 14);

    const format = (value) => String(value).padStart(2, '0');

    const updateCountdown = () => {
      const diff = targetSaleEnd - new Date();
      const totalSeconds = Math.max(0, Math.floor(diff / 1000));
      const days = Math.floor(totalSeconds / 86400);
      const hours = Math.floor((totalSeconds % 86400) / 3600);
      const minutes = Math.floor((totalSeconds % 3600) / 60);
      const seconds = totalSeconds % 60;

      document.getElementById('days').textContent = format(days);
      document.getElementById('hours').textContent = format(hours);
      document.getElementById('minutes').textContent = format(minutes);
      document.getElementById('seconds').textContent = format(seconds);
    };

    updateCountdown();
    setInterval(updateCountdown, 1000);

    newsletterForm.addEventListener('submit', (event) => {
      event.preventDefault();
      const email = document.getElementById('email');

      if (!email.validity.valid) {
        email.focus();
        newsletterHelp.textContent = 'Enter a valid email address to join the list.';
        return;
      }

      newsletterHelp.textContent = `Thanks, ${email.value}. You're on the list.`;
      newsletterForm.reset();
    });
  </script>
